package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class JsonWriter_value_TriageGen2Test {

    private JsonWriter jsonWriter;

    @Before
    public void setUp() throws IOException {
        jsonWriter = new JsonWriter(new StringWriter());
    }

    @Test
    public void testValueNull() throws IOException {
        jsonWriter.value((Number) null);
        assertEquals(nullValue().toString(), jsonWriter.toString());
    }

    @Test
    public void testValueFiniteNumber() throws IOException {
        jsonWriter.value(1);
        jsonWriter.beforeValue(false);
        jsonWriter.out.append(jsonWriter.toString());
        assertEquals("1", jsonWriter.toString());
    }

    @Test
    public void testValueInfiniteNumber() throws IOException, IllegalArgumentException {
        jsonWriter.value(Double.POSITIVE_INFINITY);
        jsonWriter.beforeValue(false);
        jsonWriter.out.append(jsonWriter.toString());
        assertEquals("Infinity", jsonWriter.toString());
    }

    @Test
    public void testValueNegativeInfiniteNumber() throws IOException, IllegalArgumentException {
        jsonWriter.value(Double.NEGATIVE_INFINITY);
        jsonWriter.beforeValue(false);
        jsonWriter.out.append(jsonWriter.toString());
        assertEquals("-Infinity", jsonWriter.toString());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValueNaNNumber() throws IOException, IllegalArgumentException {
        jsonWriter.value(Double.NaN);
        jsonWriter.beforeValue(false);
        jsonWriter.out.append(jsonWriter.toString());
    }

    @Test
    public void testValueBigDecimal() throws IOException {
        jsonWriter.value(BigDecimal.valueOf(1));
        jsonWriter.beforeValue(false);
        jsonWriter.out.append(jsonWriter.toString());
        assertEquals("1", jsonWriter.toString());
    }

    @Test
    public void testValueBigInteger() throws IOException {
        jsonWriter.value(BigInteger.valueOf(1));
        jsonWriter.beforeValue(false);
        jsonWriter.out.append(jsonWriter.toString());
        assertEquals("1", jsonWriter.toString());
    }

    @Test
    public void testValueEmptyString() throws IOException {
        jsonWriter.value(0);
        jsonWriter.beforeValue(false);
        jsonWriter.out.append(jsonWriter.toString());
        assertEquals("0", jsonWriter.toString());
    }

    @Test
    public void testValueLenient() throws IOException {
        jsonWriter.setLenient(true);
        jsonWriter.value(Double.POSITIVE_INFINITY);
        jsonWriter.beforeValue(false);
        jsonWriter.out.append(jsonWriter.toString());
        assertEquals("Infinity", jsonWriter.toString());
    }

    @Test
    public void testValueLenientEmptyString() throws IOException {
        jsonWriter.setLenient(true);
        jsonWriter.value(0);
        jsonWriter.beforeValue(false);
        jsonWriter.out.append(jsonWriter.toString());
        assertEquals("0", jsonWriter.toString());
    }

    @Test
    public void testValueLenientNaNNumber() throws IOException {
        jsonWriter.setLenient(true);
        jsonWriter.value(Double.NaN);
        jsonWriter.beforeValue(false);
        jsonWriter.out.append(jsonWriter.toString());
        assertEquals("NaN", jsonWriter.toString());
    }
}
